#IAM User
resource "aws_iam_user" "bilbo" {
  name          = "cg-bilbo-${var.cgid}"
  force_destroy = true

  tags = {
    deployment_profile = var.profile
  }

  provisioner "local-exec" {
    when    = destroy
    command = "./resource_cleaning.sh ${self.name} ${self.tags.deployment_profile}"
  }
}

resource "aws_iam_access_key" "bilbo" {
  user = aws_iam_user.bilbo.name
}

resource "aws_iam_user_policy" "standard_user" {
  name = "${aws_iam_user.bilbo.name}-standard-user-assumer"
  user = aws_iam_user.bilbo.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = ""
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = "arn:aws:iam::940877411605:role/cg-lambda-invoker*"
      },
      {
        Sid    = ""
        Effect = "Allow"
        Action = [
          "iam:Get*",
          "iam:List*",
          "iam:SimulateCustomPolicy",
          "iam:SimulatePrincipalPolicy"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "cg-lambda-invoker" {
  name = "cg-lambda-invoker-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          AWS = aws_iam_user.bilbo.arn
        }
      }
    ]
  })

  inline_policy {
    name = "lambda-invoker"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "lambda:ListFunctionEventInvokeConfigs",
            "lambda:InvokeFunction",
            "lambda:ListTags",
            "lambda:GetFunction",
            "lambda:GetPolicy"
          ]
          Resource = aws_lambda_function.policy_applier_lambda1.arn
        },
        {
          Effect = "Allow"
          Action = [
            "lambda:ListFunctions",
            "iam:Get*",
            "iam:List*",
            "iam:SimulateCustomPolicy",
            "iam:SimulatePrincipalPolicy"
          ]
          Resource = "*"
        }
      ]
    })
  }
}

# policy applier lambda 1 (vulnerable to sql injection)
resource "aws_iam_role" "policy_applier_lambda1" {
  name = "${var.cgid}-policy_applier_lambda1"

  inline_policy {
    name = "policy_applier_lambda1"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action   = "iam:AttachUserPolicy"
          Effect   = "Allow"
          Resource = aws_iam_user.bilbo.arn
        },
        {
          Effect = "Allow"
          Action = [
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource = "arn:aws:logs:${var.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/${var.cgid}-policy_applier_lambda1:*"
        }
      ]
    })
  }

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })
}

data "archive_file" "policy_applier_lambda1_zip" {
  type        = "zip"
  source_dir  = "lambda_source_code/policy_applier_lambda1_src"
  output_path = "lambda_source_code/archives/policy_applier_lambda1_src.zip"
}

resource "aws_cloudwatch_log_group" "policy_applier_lambda1" {
  name              = "/aws/lambda/${var.cgid}-policy_applier_lambda1"
  retention_in_days = 14
}

resource "aws_lambda_function" "policy_applier_lambda1" {
  depends_on = [
    aws_cloudwatch_log_group.policy_applier_lambda1
  ]

  filename         = data.archive_file.policy_applier_lambda1_zip.output_path
  function_name    = "${var.cgid}-policy_applier_lambda1"
  role             = aws_iam_role.policy_applier_lambda1.arn
  handler          = "main.handler"
  description      = "This function will apply a managed policy to the user of your choice, so long as the database says that it's okay..."
  source_code_hash = filebase64sha256(data.archive_file.policy_applier_lambda1_zip.output_path)
  runtime          = "python3.9"
}

